        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1 and vals[0] != 0:
                divider = ("col", c)
                break

    if divider[0] == "row":
        k = divider[1]
        a, b = grid[:k], grid[k + 1:]
    else:
        k = divider[1]
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    # The mostly-solid panel is the stencil; the other panel supplies the pattern.
    def zero_rate(panel):
        cells = [v for row in panel for v in row]
        return cells.count(0) / len(cells)

    if zero_rate(a) <= zero_rate(b):
        mask, pattern = a, b
    else:
        mask, pattern = b, a

    return [
        [0 if mask[r][c] == 0 or pattern[r][c] == 0 else 2
         for c in range(len(pattern[r]))]
        for r in range(len(pattern))
    ]
